def failure_extent(raw):
    """No-follow bounded accounting for diagnostics; never admission of specials."""
    need(raw.is_absolute() and raw.resolve(strict=True) == raw and raw.is_dir(), "physical diagnostic raw required")
    total, count, pending = 0, 0, [raw]
    while pending:
        parent = pending.pop()
        physical_ancestors(raw, parent)
        with os.scandir(parent) as entries:
            for item in entries:
                count += 1
                need(count <= ENTRY_LIMIT, "diagnostic entry census cap exceeded")
                observed = item.stat(follow_symlinks=False)
                if stat.S_ISDIR(observed.st_mode):
                    pending.append(Path(item.path))
                elif stat.S_ISREG(observed.st_mode) or stat.S_ISLNK(observed.st_mode):
                    total += observed.st_size
    return total


def preserve_primary_error(raw, error, phase):
    """Persist the first failure before postchecks/finalization can replace it."""
    need(raw.name == RAW_NAME and raw.parent == RAW_PARENT, "exact diagnostic namespace required")
    need(raw.is_absolute() and raw.resolve(strict=True) == raw and raw.is_dir(),
         "physical diagnostic namespace required")
    path = raw / "mixed-primary-error.json"
    if os.path.lexists(path):
        observed = path.lstat()
        need(stat.S_ISREG(observed.st_mode) and observed.st_uid == os.geteuid()
             and observed.st_size <= PRIMARY_ERROR_BYTES, "primary diagnostic must be bounded owned regular input")
        return json.loads(path.read_bytes())
    frames, tb = [], error.__traceback__
    while tb is not None:
        if len(frames) == 16:
            frames.pop(0)
        frames.append({"file": tb.tb_frame.f_code.co_filename[-512:],
                       "function": tb.tb_frame.f_code.co_name[:128], "line": tb.tb_lineno})
        tb = tb.tb_next
    result = {"status": "PRIMARY_ERROR", "error": type(error).__name__, "reason": str(error)[:4096],
        "phase": phase, "frames": frames, "source_commit": SOURCE, "independent_cold_acceptance": False}
    payload = (json.dumps(result, sort_keys=True, indent=2, allow_nan=False) + "\n").encode()
    need(len(payload) <= PRIMARY_ERROR_BYTES <= FINAL_RESERVE_BYTES - FINAL_RESULT_BYTES
         and failure_extent(raw) <= TOTAL_BYTES - FINAL_RESERVE_BYTES,
         "primary diagnostic exceeds fixed reserved budget")
    with path.open("xb") as stream:
        stream.write(payload); stream.flush(); os.fsync(stream.fileno())
    return result


def primary_error_summary(raw):
    path = raw / "mixed-primary-error.json"
    if not os.path.lexists(path):
        return None
    observed = path.lstat()
    need(stat.S_ISREG(observed.st_mode) and observed.st_uid == os.geteuid() and observed.st_size <= PRIMARY_ERROR_BYTES,
         "bounded primary diagnostic required")
    data = path.read_bytes()
    result = json.loads(data)
    return {"path": path.name, "bytes": len(data), "sha256": sha(data),
            **{key: result[key] for key in ("error", "reason", "phase")}}


def console_failure(result):
    """Each of at most two console records fits8KiB of the fixed64KiB reserve."""
    value = {"status": "REFUSED_OR_FAILED", "error": str(result.get("error", "Unknown"))[:64],
             "reason": str(result.get("reason", ""))[:192], "independent_cold_acceptance": False}
    if isinstance(result.get("primary_error"), dict):
        value["primary_error"] = {key: result["primary_error"][key] for key in ("path", "bytes", "sha256")}
    return value

